/*
 * face_pic.c — meter face backed by a stored background picture.
 *
 * The whole face, including the lamp gradient, the arc, the ticks and the
 * numerals, lives in one full-screen 480 x 320 image in the panel's flash
 * (picture ID 0), generated by nzif/meter_display/make_face.py.
 *
 * That removes the entire display list that face_drawn.c needs. There is no
 * scale to redraw, because erasing the needle is done by putting the original
 * artwork back with picq, which restores everything underneath it at once.
 *
 * The cost is that a flat-colour erase (one line command) becomes a set of
 * picq crops. Restoring the needle's whole bounding box would be ~9000 px at
 * full tilt — enough to flicker. Splitting the needle into short segments and
 * restoring a small box per segment cuts that to roughly 1000 px.
 */

#include "face.h"
#include "face_geom.h"
#include "nextion.h"

#include <math.h>
#include <string.h>
#include <stdint.h>

#include "pico/stdlib.h"

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define PIC_ID        0

/* Segments the needle is broken into when restoring the artwork behind it.
 * More segments means less wasted area but more commands; 8 puts a frame at
 * about 250 bytes, comfortable at 115200 baud and 30 fps. */
#define NEEDLE_SEGS   8

/* Grown around each restore box, to cover the needle's 3 px width and the
 * rounding in its endpoints. */
#define BOX_PAD       3

#define SWEEP_RAD  ((float)FG_SWEEP_DEG * (float)M_PI / 180.0f)

#define C_BLACK  0
#define C_READ   nex_rgb(255, 176, 86)
#define C_INK    nex_rgb(12, 9, 6)

float face_angle(float f)
{
    return -(float)M_PI * 0.5f + (2.0f * f - 1.0f) * SWEEP_RAD;
}

static void needle_pt(float a, float r, int k, int *x, int *y)
{
    float px = -sinf(a), py = cosf(a);          /* unit normal */
    *x = (int)lrintf(FG_CX + r * cosf(a) + px * (float)k);
    *y = (int)lrintf(FG_CY + r * sinf(a) + py * (float)k);
}

static void needle_draw(float f, uint16_t colour)
{
    float a = face_angle(f);
    int k;

    for (k = -1; k <= 1; k++) {
        int x0, y0, x1, y1;
        needle_pt(a, FG_NEEDLE_RIN,  k, &x0, &y0);
        needle_pt(a, FG_NEEDLE_ROUT, k, &x1, &y1);
        nex_line(x0, y0, x1, y1, colour);
    }
}

/* Put the artwork back everywhere the needle at `f` was covering. */
static void needle_restore(float f)
{
    float a = face_angle(f);
    float span = (float)(FG_NEEDLE_ROUT - FG_NEEDLE_RIN) / (float)NEEDLE_SEGS;
    int i;

    for (i = 0; i < NEEDLE_SEGS; i++) {
        float r0 = FG_NEEDLE_RIN + span * (float)i;
        float r1 = r0 + span;
        int x0, y0, x1, y1, xa, ya, xb, yb, w, h;

        needle_pt(a, r0, 0, &x0, &y0);
        needle_pt(a, r1, 0, &x1, &y1);

        xa = (x0 < x1 ? x0 : x1) - BOX_PAD;
        ya = (y0 < y1 ? y0 : y1) - BOX_PAD;
        xb = (x0 > x1 ? x0 : x1) + BOX_PAD;
        yb = (y0 > y1 ? y0 : y1) + BOX_PAD;

        if (xa < 0) { xa = 0; }
        if (ya < 0) { ya = 0; }
        if (xb > FG_SCR_W - 1) { xb = FG_SCR_W - 1; }
        if (yb > FG_SCR_H - 1) { yb = FG_SCR_H - 1; }

        w = xb - xa + 1;
        h = yb - ya + 1;
        if (w > 0 && h > 0) {
            nex_picq(xa, ya, w, h, PIC_ID);
        }
    }
}

void face_needle_first(float f)
{
    needle_draw(f, C_INK);
}

void face_needle(float from, float to)
{
    needle_restore(from);
    needle_draw(to, C_INK);
}

/* ------------------------------------------------------------------ *
 * Readout strip — plain black in the artwork, so the panel's own font
 * can be used here with a solid background.
 * ------------------------------------------------------------------ */

#define CELLS   3
#define CELL_W  (FG_SCR_W / CELLS)
#define CELL_Y  254
#define CELL_H  42

static char g_cell[CELLS][20];

void face_readout(int cell, const char *text)
{
    if (cell < 0 || cell >= CELLS) {
        return;
    }
    if (strncmp(g_cell[cell], text, sizeof(g_cell[0])) == 0) {
        return;
    }
    strncpy(g_cell[cell], text, sizeof(g_cell[0]) - 1);
    g_cell[cell][sizeof(g_cell[0]) - 1] = '\0';
    nex_text(cell * CELL_W, CELL_Y, CELL_W, CELL_H, C_READ, C_BLACK, 1, text);
}

void face_init(void)
{
    int i;

    /* One command replaces the ~226 line commands face_drawn.c needed. */
    nex_pic(0, 0, PIC_ID);
    sleep_ms(120);

    for (i = 0; i < CELLS; i++) {
        g_cell[i][0] = '\0';
    }
}
